function normalizeArea(value){return String(value??'').toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').replace(/(.)\1+/g,'$1').replace(/kattapana/g,'kattappana').trim()}
function areaMatches(listingArea,selectedArea){const area=normalizeArea(listingArea),parts=String(selectedArea||'').split(',').map(normalizeArea).filter(Boolean);return !parts.length||parts.some(part=>area.includes(part)||part.includes(area))}
function distanceKm(a,b){const rad=value=>value*Math.PI/180,lat=rad(b.lat-a.lat),lon=rad(b.lon-a.lon),h=Math.sin(lat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(lon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
