function coordinatesForArea(value){const normalized=normalizeArea(value);const place=coordinatePlaceNames.find(name=>normalized.includes(normalizeArea(name)));if(!place)return null;const [lat,lon]=nearbyPlaceCoordinates[place];return{lat,lon,label:place}}
