function recentTimestamp(item,index){const raw=item.created_at||item.createdAt||item.posted_at||item.postedAt;if(raw){const time=Date.parse(raw);if(Number.isFinite(time))return time}const label=String(item.time||'').toLowerCase();if(/today/.test(label))return Date.now()-index;if(/yesterday/.test(label))return Date.now()-86400000-index;const days=label.match(/(\d+)\s*days?\s*ago/);if(days)return Date.now()-Number(days[1])*86400000-index;return 0}
