function updateUnreadMessages(){const count=unreadConversationIds.size,targets=[$('#messagesBtn'),$('#mobileChats')].filter(Boolean);targets.forEach(button=>{const label=count?`Chats, ${count} unread chat${count===1?'':'s'}`:'Chats';if(count){button.dataset.unread=String(count>99?'99+':count)}else delete button.dataset.unread;button.title=label;button.setAttribute('aria-label',label)});const visual=$('.chat-unread-label');if(visual)visual.textContent=count?`${count>99?'99+':count} unread`:''}
