function trackConversationForNotifications(id){if(id)observedConversationIds.add(id)}
async function refreshUnreadMessages(uid=user?.id,knownConversations=null){if(!sbClient||!uid||uid!==user?.id||!isRealUser()){unreadConversationIds.clear();updateUnreadMessages();return}let rows=knownConversations;if(!rows){const [buying,selling]=await Promise.all([sbClient.from('conversations').select('id,listing_id').eq('buyer_id',uid),sbClient.from('conversations').select('id,listing_id').eq('seller_id',uid)]);if(user?.id!==uid||buying.error||selling.error){if(buying.error||selling.error)console.warn('Could not refresh unread chats:',buying.error?.message||selling.error?.message);return}rows=[...(buying.data||[]),...(selling.data||[])]}const conversations=[...new Map(rows.map(row=>[row.id,row])).values()].filter(row=>listings.some(item=>item.id===row.listing_id));if(!conversations.length){unreadConversationIds.clear();updateUnreadMessages();return}const ids=conversations.map(row=>row.id),{data:messages,error}=await sbClient.from('messages').select('conversation_id,sender_id,created_at').in('conversation_id',ids).neq('sender_id',uid).order('created_at',{ascending:false}).limit(5000);if(user?.id!==uid||error){if(error)console.warn('Could not check unread messages:',error.message);return}const latest=new Map();for(const message of messages||[])if(!latest.has(message.conversation_id))latest.set(message.conversation_id,message.created_at);const cursors=readCursors(),unread=new Set();for(const row of conversations){const lastIncoming=latest.get(row.id);if(!lastIncoming)continue;if(!Object.hasOwn(cursors,row.id)||Date.parse(lastIncoming)>Date.parse(cursors[row.id]))unread.add(row.id)}unreadConversationIds=unread;updateUnreadMessages()}
async function setupMessageNotifications(){const uid=isRealUser()?user.id:null;if(uid===notificationUserId&&(notificationChannel||!uid))return;if(notificationChannel&&sbClient)await sbClient.removeChannel(notificationChannel);notificationChannel=null;notificationUserId=uid;observedConversationIds.clear();unreadConversationIds.clear();updateUnreadMessages();if(!uid||!sbClient)return;const [buying,selling]=await Promise.all([sbClient.from('conversations').select('id').eq('buyer_id',uid),sbClient.from('conversations').select('id').eq('seller_id',uid)]);if(user?.id!==uid)return;if(buying.error||selling.error){console.warn('Could not load conversations for message notifications:',buying.error?.message||selling.error?.message);return}[...(buying.data||[]),...(selling.data||[])].forEach(row=>trackConversationForNotifications(row.id));await refreshUnreadMessages(uid);if(user?.id!==uid)return;notificationChannel=sbClient.channel('redo-notifications:'+uid).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages'},async payload=>{const message=payload.new;if(!message||message.sender_id===user?.id)return;if(!observedConversationIds.has(message.conversation_id)){const {data,error}=await sbClient.from('conversations').select('id,buyer_id,seller_id,listing_id').eq('id',message.conversation_id).maybeSingle();if(user?.id!==uid||error||!data||![data.buyer_id,data.seller_id].includes(uid))return;trackConversationForNotifications(data.id)}if(user?.id!==uid)return;if(currentConversationId===message.conversation_id)markConversationRead(message.conversation_id,message.created_at);else await refreshUnreadMessages(uid);fetchPublicNames([message.sender_id]).then(names=>{if(user?.id===uid)toast(`New message from ${names[message.sender_id]||'someone'}.`)})}).on('postgres_changes',{event:'DELETE',schema:'public',table:'messages'},()=>refreshUnreadMessages(uid)).subscribe()}
async function loadListings(){if(!sbClient){listingsLoading=false;return}let result=await sbClient.from('listings').select('id,user_id,category,subcategory,price,title,area,state,district,town,condition,specs,photo_url,photo_urls,seller_name,description,created_at,status').eq('status','active').order('created_at',{ascending:false}).limit(100);if(result.error&&/column .* does not exist|schema cache|could not find the .* column/i.test(result.error.message)){result=await sbClient.from('listings').select('id,user_id,category,price,title,area,photo_url,description,created_at,status').eq('status','active').order('created_at',{ascending:false}).limit(100)}listingsLoading=false;if(result.error){renderListings();toast(`Could not load marketplace data: ${result.error.message}`);return}const mapped=(result.data||[]).map(mapListing),names=await fetchPublicNames(mapped.map(item=>item.user_id));listings=mapped.map(item=>({...item,seller_name:names[item.user_id]||item.seller_name}));renderListings()}
