const mlUiReverse=Object.fromEntries(Object.entries(mlUiText).map(([en,ml])=>[ml,en]));
function translateUiText(value,useMl){const text=String(value??'').trim();if(!text)return value;if(useMl){if(mlUiText[text])return mlUiText[text];let match=text.match(/^New message from (.+)\.$/i);if(match)return `പുതിയ സന്ദേശം: ${match[1]}`;match=text.match(/^(\d+) photos?$/i);if(match)return `${match[1]} ഫോട്ടോ${match[1]==='1'?'':'കൾ'}`;match=text.match(/^(\d+) finds?$/i);if(match)return `${match[1]} പരസ്യങ്ങൾ`;match=text.match(/^More in (.+)$/i);if(match)return `ഇതേ വിഭാഗത്തിൽ കൂടുതൽ: ${malayalamLabels[match[1]]||match[1]}`;match=text.match(/^Showing finds around (.+)\.$/i);if(match)return `ഈ സ്ഥലത്തിന് സമീപമുള്ള പരസ്യങ്ങൾ കാണിക്കുന്നു: ${match[1]}`;match=text.match(/^Showing finds within (\d+) km of (.+)\.$/i);if(match)return `${match[2]}-ൽ നിന്ന് ${match[1]} കി.മീ. പരിധിയിലുള്ള പരസ്യങ്ങൾ`;match=text.match(/^(\d+) locally saved finds?; synced account favorites are kept separately\.$/i);if(match)return `${match[1]} പരസ്യങ്ങൾ ഈ ഉപകരണത്തിൽ സൂക്ഷിച്ചിട്ടുണ്ട്; അക്കൗണ്ടിലെ പ്രിയപ്പെട്ടവ വേറെയും സൂക്ഷിക്കും.`;return value}return mlUiReverse[text]||value}
function translateInterface(root=document.body,useMl=document.documentElement.lang==='ml'){
 if(!root)return;const keepData='.listing-title,.listing-desc,.listing-meta,.product-condition,.product-detail-price,.product-price-card h1,.product-location-line,.product-description p,.product-specs dd,.related-item b,.related-item small,.product-seller-name,.product-seller-place,.product-seller-row b,.conversation-preview,.conversation-title b,.conversation-meta,.chat-message p,.chat-bubble small,.chat-peer-place,.settings-account-chip b,.settings-account-chip small,.listing-review-avatar,.listing-info .listing-price';
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(node.parentElement?.closest(keepData))continue;const current=node.nodeValue||'',trimmed=current.trim();if(!trimmed)continue;const translated=translateUiText(trimmed,useMl);if(translated!==trimmed)node.nodeValue=current.replace(trimmed,translated)}
 const attrMap={placeholder:true,title:true,'aria-label':true};root.querySelectorAll?.('*').forEach(el=>{if(el.matches?.('img')&&el.closest?.('.listing-card,.conversation-card,.product-gallery'))return;for(const attr of Object.keys(attrMap)){const value=el.getAttribute(attr);if(value){let next=translateUiText(value,useMl);const photoLabel=value.match(/^Show photo (\d+)$/);if(useMl&&photoLabel)next=`ഫോട്ടോ ${photoLabel[1]} കാണുക`;if(next!==value)el.setAttribute(attr,next)}}});
}
